// ============================================================
// STEP 1: Extract all emails and get pre-extracted attachment text
// ============================================================
const input = $input.first().json;
const data = input.body || input;
const emailsArray = data.emails || [];

if (emailsArray.length === 0 && data.email) {
  emailsArray.push(data.email);
}
if (emailsArray.length === 0) {
  throw new Error('No emails found. Keys: ' + Object.keys(data).join(', '));
}

// Build Agent 1 prompt: classify from subject + body ONLY
let classifyInput = '';
let emailMetadata = [];
let attachmentTexts = [];

for (let i = 0; i < emailsArray.length; i++) {
  const email = emailsArray[i];

  classifyInput += '\n===== EMAIL ' + (i + 1) + ' =====\n';
  classifyInput += 'From: ' + email.from_name + ' <' + email.from_email + '>\n';
  classifyInput += 'To: ' + email.to_name + ' <' + email.to_email + '>\n';
  classifyInput += 'Subject: ' + email.subject + '\n';
  classifyInput += 'Body:\n' + email.body_plain + '\n';

  emailMetadata.push({
    email_index: email.email_index != null ? email.email_index : i,
    id: email.id,
    from_name: email.from_name,
    from_email: email.from_email,
    to_name: email.to_name,
    to_email: email.to_email,
    subject: email.subject,
    body_plain: email.body_plain,
    received_at: email.received_at,
    attachment_names: (email.attachments || []).map(a => a.file_name)
  });

  // Get pre-extracted text from attachments (sent by HTML alongside base64)
  const emailAttTexts = [];
  const attachments = email.attachments || [];
  for (let j = 0; j < attachments.length; j++) {
    const att = attachments[j];
    emailAttTexts.push({
      file_name: att.file_name,
      file_type: att.file_type || '',
      file_category: att.file_category || '',
      extracted_text: att.file_content_text || 'No text content available'
    });
  }
  attachmentTexts.push(emailAttTexts);
}

const classifyPrompt = 'You are an insurance email triage specialist. Read the following ' + emailsArray.length + ' emails (subject and body only) and classify each into exactly ONE scenario.\n\nSCENARIO TYPES:\n- "BOR" - Broker of Record: Email requests a change of broker, broker appointment, or BOR transfer\n- "Cancellation" - Policy Cancellation: Email requests to cancel an insurance policy\n- "Quote" - Quote Request: Email requests a new insurance quote or pricing\n- "Endorsement" - Policy endorsement or change request\n- "Renewal" - Policy renewal request\n- "Claim" - Insurance claim filing\n- "Other" - None of the above\n\nHOW TO CLASSIFY:\n- Look at the subject line first - it usually states the intent clearly\n- Confirm with the email body\n- "Broker of Record" or "BOR" in subject/body = BOR\n- "Cancellation" or "cancel" in subject/body = Cancellation\n- "Quote" in subject/body = Quote\n\nEMAILS TO CLASSIFY:\n' + classifyInput + '\n\nReturn ONLY a JSON array with no markdown, no code blocks, no extra text:\n[\n  { "email_index": 0, "scenario": "<BOR|Cancellation|Quote|Endorsement|Renewal|Claim|Other>", "reason": "<one sentence why>" }\n]';

return [{
  json: {
    emailMetadata,
    attachmentTexts,
    classifyPrompt,
    totalEmails: emailsArray.length
  }
}];

// ============================================================
// Parse Agent 1 results, build Agent 2 prompt with REAL attachment text
// ============================================================
const input = $input.first().json;
const prepData = $('Prepare Data').first().json;
const emailMetadata = prepData.emailMetadata;
const attachmentTexts = prepData.attachmentTexts;

// Parse Agent 1 response
let classifications = [];
let rawContent = '';
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  rawContent = choices[0].message.content.trim();
  let jsonStr = rawContent;
  if (jsonStr.startsWith('```')) {
    jsonStr = jsonStr.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  classifications = JSON.parse(jsonStr);
  if (!Array.isArray(classifications)) classifications = [classifications];
} catch(e) {
  for (let i = 0; i < emailMetadata.length; i++) {
    classifications.push({ email_index: i, scenario: 'Unknown', reason: 'Parse error: ' + e.message });
  }
}

// Build Agent 2 prompt with REAL extracted text from attachments
let extractionInput = '';
for (let i = 0; i < emailMetadata.length; i++) {
  const meta = emailMetadata[i];
  const atts = attachmentTexts[i] || [];
  const scenario = (classifications[i] || {}).scenario || 'Unknown';

  extractionInput += '\n===== EMAIL ' + (i + 1) + ' (Scenario: ' + scenario + ') =====\n';
  extractionInput += 'Subject: ' + meta.subject + '\n';
  extractionInput += 'Body: ' + meta.body_plain + '\n';

  for (let j = 0; j < atts.length; j++) {
    extractionInput += '\n--- Attachment: ' + atts[j].file_name + ' (' + atts[j].file_category + ') ---\n';
    extractionInput += 'DOCUMENT CONTENT:\n' + atts[j].extracted_text + '\n';
  }
}

const extractPrompt = 'You are an insurance document data extraction specialist. Below are ' + emailMetadata.length + ' emails with the FULL TEXT CONTENT extracted from their PDF and DOCX attachments.\n\nFor EACH email, carefully read the attachment text content and extract the following fields. The data IS present in the document text - look carefully.\n\nFIELDS TO EXTRACT:\n- policy_number: Policy number (e.g. AUTO-TX-4589231). Look for "Policy Number:" in the text.\n- vin_number: Vehicle Identification Number. Look for "VIN:" in the text.\n- policy_type: Type of insurance (e.g. Personal Auto Insurance, Collector Vehicle). Look for "Policy Type:" or "Vehicle Type:" in the text.\n- insurance_carrier: Insurance company name. Look for "Insurance Carrier:" in the text.\n- customer_id: Customer or client ID number. Return "Not found" if not in the text.\n- quote_number: Quote reference number. Return "Not found" if not in the text.\n- customer_name: Full name of insured/applicant. Look for "Insured Name:", "Full Name:", or "Policyholder Name:" in the text.\n- license_number: Driver license number. Return "Not found" if not in the text.\n- attachment_type: Describe what kind of documents are attached (e.g. "BOR Letter", "Cancellation Form + Proof of Sale", "Vehicle Insurance Application").\n- email_subject: The email subject line.\n- email_body_summary: 2-3 sentence summary of the email.\n\nIMPORTANT: The document text content below contains the actual data from the PDF/DOCX files. Read it carefully and extract the values. Only return "Not found" if the field truly does not exist in the text.\n\nEMAILS AND THEIR ATTACHMENT CONTENTS:\n' + extractionInput + '\n\nReturn ONLY a JSON array (no markdown, no code blocks, no extra text):\n[\n  {\n    "email_index": 0,\n    "policy_number": "<value or Not found>",\n    "vin_number": "<value or Not found>",\n    "policy_type": "<value or Not found>",\n    "insurance_carrier": "<value or Not found>",\n    "customer_id": "<value or Not found>",\n    "quote_number": "<value or Not found>",\n    "customer_name": "<value or Not found>",\n    "license_number": "<value or Not found>",\n    "attachment_type": "<description>",\n    "email_subject": "<subject>",\n    "email_body_summary": "<summary>"\n  }\n]';

return [{
  json: {
    classifications,
    emailMetadata,
    attachmentTexts,
    extractPrompt
  }
}];

// ============================================================
// Combine Agent 1 + Agent 2 results, build Agent 3 response prompt
// ============================================================
const input = $input.first().json;
const prevData = $('Parse Classification & Prepare Extraction').first().json;
const classifications = prevData.classifications;
const emailMetadata = prevData.emailMetadata;

// Parse Agent 2 extraction results
let extractions = [];
let rawContent = '';
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  rawContent = choices[0].message.content.trim();
  let jsonStr = rawContent;
  if (jsonStr.startsWith('```')) {
    jsonStr = jsonStr.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  extractions = JSON.parse(jsonStr);
  if (!Array.isArray(extractions)) extractions = [extractions];
} catch(e) {
  for (let i = 0; i < emailMetadata.length; i++) {
    extractions.push({
      email_index: i, policy_number: 'Not found', vin_number: 'Not found',
      policy_type: 'Not found', insurance_carrier: 'Not found',
      customer_id: 'Not found', quote_number: 'Not found',
      customer_name: 'Not found', license_number: 'Not found',
      attachment_type: 'Not found', email_subject: emailMetadata[i].subject,
      email_body_summary: 'Extraction error: ' + e.message
    });
  }
}

// Build combined summary for Agent 3
let responseSummary = '';
for (let i = 0; i < emailMetadata.length; i++) {
  const meta = emailMetadata[i];
  const classif = classifications[i] || {};
  const extract = extractions[i] || {};

  responseSummary += '\n===== EMAIL ' + (i + 1) + ' =====\n';
  responseSummary += 'From: ' + meta.from_name + ' <' + meta.from_email + '>\n';
  responseSummary += 'Subject: ' + meta.subject + '\n';
  responseSummary += 'Email Scenario: ' + (classif.scenario || 'Unknown') + '\n';
  responseSummary += 'Classification Reason: ' + (classif.reason || 'N/A') + '\n';
  responseSummary += 'Attachments: ' + meta.attachment_names.join(', ') + '\n';
  responseSummary += '\nExtracted Key Details:\n';
  responseSummary += '- Policy Number: ' + (extract.policy_number || 'Not found') + '\n';
  responseSummary += '- VIN Number: ' + (extract.vin_number || 'Not found') + '\n';
  responseSummary += '- Policy Type: ' + (extract.policy_type || 'Not found') + '\n';
  responseSummary += '- Insurance Carrier: ' + (extract.insurance_carrier || 'Not found') + '\n';
  responseSummary += '- Customer ID: ' + (extract.customer_id || 'Not found') + '\n';
  responseSummary += '- Quote Number: ' + (extract.quote_number || 'Not found') + '\n';
  responseSummary += '- Customer Name: ' + (extract.customer_name || 'Not found') + '\n';
  responseSummary += '- License Number: ' + (extract.license_number || 'Not found') + '\n';
  responseSummary += '- Attachment Type: ' + (extract.attachment_type || 'Not found') + '\n';
}

const responsePrompt = 'You are a professional insurance operations assistant at Wonderland Global Insurance. Generate a professional response email for EACH of the ' + emailMetadata.length + ' emails below.\n\nFor each response:\n1. Address the sender by name\n2. Acknowledge receipt of their email and ALL attachments by filename\n3. State: "Email Scenario: <scenario>" clearly\n4. List ALL extracted key details in a clean format:\n   - Policy Number: <value>\n   - VIN Number: <value>\n   - Policy Type: <value>\n   - Insurance Carrier: <value>\n   - Customer ID: <value>\n   - Quote Number: <value>\n   - Customer Name: <value>\n   - License Number: <value>\n   - Attachment Type: <value>\n5. For items marked "Not found", say: "This detail was not found in the provided documents. Please provide this information at your earliest convenience."\n6. Add category-specific next steps:\n   - BOR: "Your Broker of Record change request is being processed. The transfer will be completed within 5-7 business days."\n   - Cancellation: "Your cancellation request has been received. We will process the cancellation and any applicable refund will be calculated and communicated within 3-5 business days."\n   - Quote: "Your quote request and application have been received. Our underwriting team will review the details and provide a quote within 2-3 business days."\n7. Sign as:\n   Best Regards,\n   Wonderland Team\n   Email Processing Division\n   Emailprocessing@wonderlandglobal.com\n   Phone: (800) 555-0199\n\nEMAILS WITH CLASSIFICATION AND EXTRACTED DETAILS:\n' + responseSummary + '\n\nReturn ONLY a JSON array (no markdown, no code blocks):\n[\n  { "email_index": 0, "response_body": "<full professional response>" }\n]';

return [{
  json: {
    classifications,
    extractions,
    emailMetadata,
    responsePrompt
  }
}];

// ============================================================
// Build the final webhook response to send back to HTML
// ============================================================
const input = $input.first().json;
const prevData = $('Combine Results & Prepare Response').first().json;
const classifications = prevData.classifications || [];
const extractions = prevData.extractions || [];
const emailMetadata = prevData.emailMetadata || [];

// Parse Agent 3 generated responses
let responses = [];
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  let content = choices[0].message.content.trim();
  if (content.startsWith('```')) {
    content = content.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  responses = JSON.parse(content);
  if (!Array.isArray(responses)) responses = [responses];
} catch(e) {
  for (let i = 0; i < emailMetadata.length; i++) {
    const c = classifications[i] || {};
    responses.push({
      email_index: i,
      response_body: 'Dear ' + emailMetadata[i].from_name + ',\n\nThank you for your email regarding "' + emailMetadata[i].subject + '".\n\nEmail Scenario: ' + (c.scenario || 'Under Review') + '\n\nWe have received your request and attached documents. Our team is currently reviewing the details and will respond with a full assessment shortly.\n\nBest Regards,\nWonderland Team\nEmail Processing Division\nEmailprocessing@wonderlandglobal.com\nPhone: (800) 555-0199'
    });
  }
}

// Build final results array
const results = [];
for (let i = 0; i < emailMetadata.length; i++) {
  const meta = emailMetadata[i];
  const classif = classifications[i] || {};
  const extract = extractions[i] || {};
  const resp = responses.find(r => r.email_index === i) || responses[i] || {};

  results.push({
    email_index: meta.email_index != null ? meta.email_index : i,
    email_id: meta.id || null,
    email_subject: meta.subject,
    classification: {
      category: classif.scenario || 'Unknown',
      reason: classif.reason || ''
    },
    extracted_details: {
      policy_number: extract.policy_number || 'Not found',
      vin_number: extract.vin_number || 'Not found',
      policy_type: extract.policy_type || 'Not found',
      insurance_carrier: extract.insurance_carrier || 'Not found',
      customer_id: extract.customer_id || 'Not found',
      quote_number: extract.quote_number || 'Not found',
      customer_name: extract.customer_name || 'Not found',
      license_number: extract.license_number || 'Not found',
      attachment_type: extract.attachment_type || 'Not found',
      email_subject: extract.email_subject || meta.subject,
      email_body_summary: extract.email_body_summary || ''
    },
    response: {
      from_name: 'Wonderland Team',
      from_email: 'Emailprocessing@wonderlandglobal.com',
      to_name: meta.from_name,
      to_email: meta.from_email,
      subject: 'RE: ' + meta.subject,
      body: resp.response_body || 'Thank you for your email. We are processing your request.',
      sent_at: new Date().toISOString()
    },
    attachments_processed: meta.attachment_names || []
  });
}

return [{
  json: {
    success: true,
    total_processed: results.length,
    processed_at: new Date().toISOString(),
    results
  }
}];
